import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`faceless-youtube`,heroTitle:`Launch a faceless YouTube channel in minutes`,heroSubtitle:`Perplexity Computer researches your niche, scripts your videos, and builds a full content pipeline — automatically.`,inputUrlCta:`Build my channel`,inputUrlPlaceholder:`e.g. youtube.com/@channel`,inputUrlPrefill:`Go to {url} and analyze this YouTube niche or channel. 1) Identify the top-performing faceless video formats, topics, and styles in this niche — study thumbnails, titles, video length, posting frequency, and engagement patterns. 2) Research the top 10 competing faceless channels and break down what makes their best videos succeed. 3) Build a 30-day content calendar with 12 video ideas, each including a working title, hook, full script (optimized for AI voiceover), thumbnail concept, and SEO-optimized description with tags. 4) For each script, include specific B-roll and stock footage direction so the video can be assembled without a camera. 5) Recommend the best AI voiceover style, background music mood, and editing pace for this niche. 6) Deliver a channel setup guide — channel name options, banner concept, about section copy, and keyword strategy to maximize discoverability from day one.`,heroOverlaySteps:[`Analyzing your niche for top-performing faceless formats`,`Researching competitor channels and viral patterns`,`Scripting videos with hooks, B-roll direction, and SEO tags`,`30-day content calendar and channel strategy — ready to launch`],generatingSteps:[`Visiting {url} to study niche trends, competitors, and viral formats`,`Designing an agent to script faceless videos with hooks, voiceover cues, and B-roll direction`,`Configuring SEO optimization for titles, descriptions, tags, and thumbnails`,`Setting up your 30-day content calendar and channel launch guide`],featureSectionTitle:`From niche to content machine`,featureCardTitles:[`Connects to your creator stack`,`Outputs you can publish`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Sheets, Google Drive, Notion, Canva, Airtable — Computer pipes scripts, calendars, and thumbnail briefs straight into the tools you already use.`,`Full video scripts with voiceover cues. B-roll shot lists. SEO-optimized titles and descriptions. Thumbnail concepts. A 30-day content calendar ready to execute.`],capabilitySectionTitle:`Your content team, on autopilot`,capabilitySectionSubtitle:`Paste a channel or niche, step away, come back to a full production pipeline.`,capabilityCards:[{title:`Niche Research`,description:`Computer can analyze top faceless channels in your niche — breaking down what formats, lengths, and hooks drive the most views and subscribers.`},{title:`Script Writing`,description:`Computer can write complete video scripts — with attention hooks, narrative arcs, voiceover cues, and B-roll direction for camera-free production.`},{title:`SEO Optimization`,description:`Computer can craft titles, descriptions, and tags engineered for YouTube search and suggested — so your faceless videos get discovered.`},{title:`Connect Your Tools`,description:`Computer can push scripts to Google Docs, calendars to Notion, thumbnail briefs to Canva, and tracking sheets to Airtable — all in one workflow.`},{title:`Learn Your Style`,description:`Computer can remember your niche, tone, top performers, and audience preferences — so every batch of scripts gets sharper over time.`},{title:`Monitor & Alert`,description:`Computer can track competitor uploads and trending topics in your niche — and flag new video opportunities before they peak.`}]});export{t as default};
